import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { imageAlt, splitImageAlt } from '../src/imagesize';

// Same vectors as mlcext (testdata/imagesize.json, generated by TestImageSizeVectors).
const vectors = JSON.parse(
  readFileSync(resolve(process.cwd(), '../../mlcext/testdata/imagesize.json'), 'utf8'),
) as { alt: string; text: string; size: Record<string, number>; error?: boolean }[];

describe('image size = mlcext', () => {
  for (const v of vectors) {
    it(JSON.stringify(v.alt), () => {
      expect(splitImageAlt(v.alt)).toEqual({ text: v.text, size: v.size, error: v.error ?? false });
      if (!v.error && Object.keys(v.size).length > 0) {
        expect(splitImageAlt(imageAlt(v.text, v.size))).toEqual({ text: v.text, size: v.size, error: false });
      }
    });
  }
});
